```python
def longest_subsequence(numbers):
    if not numbers:
        return "No subsequence found."

    n = len(numbers)
    dp_inc = [1] * n
    dp_dec = [1] * n

    for i in range(1, n):
        for j in range(i):
            if numbers[i] > numbers[j]:
                dp_inc[i] = max(dp_inc[i], dp_inc[j] + 1)
            elif numbers[i] < numbers[j]:
                dp_dec[i] = max(dp_dec[i], dp_dec[j] + 1)

    max_length = max(dp_inc[-1], dp_dec[-1])
    subsequence = []

    if max_length == dp_inc[-1]:
        for i in range(n - 1, -1, -1):
            if dp_inc[i] == max_length:
                subsequence.append(numbers[i])
                max_length -= 1

    elif max_length == dp_dec[-1]:
        for i in range(n - 1, -1, -1):
            if dp_dec[i] == max_length:
                subsequence.append(numbers[i])
                max_length -= 1

    return f"Longest {('increasing', 'decreasing'')[max_length % 2]} subsequence: {''.join(str(num) for num in subsequence[::-1])}"


# Test the function
sample_input = [1, 2, 3, 4, 5, 4, 3, 2, 1]
print(longest_subsequence(sample_input))  # Output: Longest decreasing subsequence: 4
